{
  "@type": "Question",
  "name": "Which image formats can I convert between?",
  "acceptedAnswer": { "@type": "Answer", "text": "You can convert images between PNG, JPG (JPEG), WebP, and AVIF formats. All conversions happen instantly in your browser with no file upload to any server." }
},
{
  "@type": "Question",
  "name": "What is AVIF and why should I use it?",
  "acceptedAnswer": { "@type": "Answer", "text": "AVIF is a modern image format that offers significantly better compression than JPG or PNG while maintaining higher visual quality. It is ideal for websites as it reduces page load times. Most modern browsers including Chrome, Firefox, and Safari support AVIF." }
},
{
  "@type": "Question",
  "name": "Will converting PNG to JPG lose quality?",
  "acceptedAnswer": { "@type": "Answer", "text": "PNG to JPG conversion does involve some quality reduction because JPG uses lossy compression. However, at standard quality settings the difference is not visible to the naked eye. For images that need a transparent background, always keep PNG format." }
},
{
  "@type": "Question",
  "name": "Why should I convert JPG to WebP?",
  "acceptedAnswer": { "@type": "Answer", "text": "WebP images are typically 25–35% smaller than equivalent JPG files at the same visual quality. Converting to WebP reduces your website page size and improves Google PageSpeed scores, which helps with SEO rankings." }
},
{
  "@type": "Question",
  "name": "Can I convert images on my phone?",
  "acceptedAnswer": { "@type": "Answer", "text": "Yes. The image format converter works fully on mobile browsers. Upload from your phone gallery, select the output format, and download the converted file directly to your device." }
}

